var lvl=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name==Tama.Args.Get(args,"level",""));
var top=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name==Tama.Args.Get(args,"topLevel",""));
var plan=new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>().First(v=>!v.IsTemplate&&v.ViewType==ViewType.FloorPlan&&v.GenLevel!=null&&v.GenLevel.Id==lvl.Id);
var comment=Tama.Args.Get(args,"comment","");
var rt=new FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Architecture.RailingType)).Cast<Element>().First(r=>r.Name==Tama.Args.Get(args,"railingType","Glass Panel - Bottom Fill"));
var sp=SketchPlane.Create(doc,Plane.CreateByNormalAndOrigin(XYZ.BasisZ,new XYZ(0,0,lvl.Elevation)));
var rails=new List<int>(); int seps=0;
foreach(var o in (object[])args["balustrades"]){
  var pts=((object[])o).Select(q=>{var a=(object[])q;return new XYZ(Convert.ToDouble(a[0])/304.8,Convert.ToDouble(a[1])/304.8,lvl.Elevation);}).ToList();
  var loop=new CurveLoop(); var ca=new CurveArray();
  for(int i=0;i<pts.Count-1;i++){ var l=Line.CreateBound(pts[i],pts[i+1]); loop.Append(l); ca.Append(l);}
  var r=Autodesk.Revit.DB.Architecture.Railing.Create(doc,loop,rt.Id,lvl.Id);
  r.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set(comment); rails.Add(r.Id.IntegerValue);
  seps+=doc.Create.NewRoomBoundaryLines(sp,ca,plan).Size;
}
doc.Regenerate();
var placed=new List<object>(); var merged=new List<string>(); var failed=new List<string>();
foreach(var o in (object[])args["rooms"]){ var a=(object[])o;
  double x=Convert.ToDouble(a[0])/304.8,y=Convert.ToDouble(a[1])/304.8; string name=a[2].ToString(), unit=a[3].ToString();
  var p=new XYZ(x,y,lvl.Elevation+1.0);
  var ex=doc.GetRoomAtPoint(p);
  if(ex!=null){ string en=ex.Name.Replace(" "+ex.Number,"");
    var np=ex.get_Parameter(BuiltInParameter.ROOM_NAME);
    if(name=="Kitchen" && np.AsString()=="Living & Dining") np.Set("Living, Dining & Kitchen");
    merged.Add(name+" ("+unit+") -> "+np.AsString()); continue; }
  var rm=doc.Create.NewRoom(lvl,new UV(x,y));
  if(rm==null||rm.Location==null){ failed.Add(name+" "+unit); continue; }
  rm.get_Parameter(BuiltInParameter.ROOM_NAME).Set(name);
  rm.get_Parameter(BuiltInParameter.ROOM_DEPARTMENT).Set(unit);
  rm.get_Parameter(BuiltInParameter.ROOM_UPPER_LEVEL).Set(top.Id);
  rm.get_Parameter(BuiltInParameter.ROOM_UPPER_OFFSET).Set(0);
  rm.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set(comment);
  doc.Regenerate();
  if(rm.Area<=0){ failed.Add(name+" "+unit+" (unbounded)"); }
  placed.Add(new{name,unit,id=rm.Id.IntegerValue,area=Math.Round(rm.Area*0.09290304,2)});
}
// number rooms per department, only when asked
if(Tama.Args.Get(args,"renumber",false)) foreach(var g in new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).Cast<Autodesk.Revit.DB.Architecture.Room>().Where(r=>r.LevelId==lvl.Id).GroupBy(r=>r.get_Parameter(BuiltInParameter.ROOM_DEPARTMENT).AsString()??"")){
  int n=1; string pre=g.Key.Trim().Length>0?g.Key.Trim().Split(' ')[0]:"R";
  foreach(var r in g.OrderByDescending(r=>r.Area)){ r.Number=pre+"-"+(n++).ToString("00"); } }
return new{rails,separationLines=seps,placedCount=placed.Count,failed,merged,placed};
